script:
export const meta = {
  name: 'digestio-ayudawp',
  description: 'Fusiona cada troballa de l\'extrapolació AyudaWP amb el seu veredicte de refutació en un resum compacte i corregit',
  phases: [{ title: 'Digestió', detail: 'una agent per tram del resultat' }],
}

const OUT = '/private/tmp/claude-501/-Users-javillinares-Documents-Antigravity-Som-de-Poble-socdepoble-org/408ff5cc-31db-4183-8175-f1acf056cb76/tasks/wkgjj1w0k.output'
const TRAMS = [
  { key: 'f0', from: 1976, to: 3498 }, { key: 'f1', from: 3499, to: 4636 }, { key: 'f2', from: 4637, to: 5993 },
  { key: 'f3', from: 5994, to: 7182 }, { key: 'f4', from: 7183, to: 8197 }, { key: 'f5', from: 8198, to: 9643 },
  { key: 'f6', from: 9644, to: 10369 }, { key: 'f7', from: 10370, to: 11228 },
  { key: 'annex-a', from: 11229, to: 13200 }, { key: 'annex-b', from: 13200, to: 15200 },
  { key: 'forats-a', from: 15258, to: 16531 }, { key: 'forats-b', from: 16532, to: 17914 }, { key: 'forats-c', from: 17915, to: 23994 },
]
const SCHEMA = {
  type: 'object',
  properties: {
    tram: { type: 'string' },
    filosofies: { type: 'array', items: { type: 'object', properties: { bloc: { type: 'string' }, text: { type: 'string', description: 'màx. 80 paraules' } }, required: ['bloc', 'text'] } },
    troballes: { type: 'array', items: { type: 'object', properties: {
      id: { type: 'string' }, wp_refs: { type: 'string' },
      principi: { type: 'string', description: 'màx. 25 paraules' },
      equivalent_sdp: { type: 'string', description: 'màx. 45 paraules' },
      estat_final: { type: 'string', enum: ['existeix', 'parcial', 'absent', 'no_aplica'] },
      severitat_final: { type: 'string', enum: ['alta', 'mitjana', 'baixa', 'cap'] },
      evidencia_clau: { type: 'string', description: 'màx. 3 referències ruta:línia, les que el veredicte ha confirmat' },
      proposta: { type: 'string', description: 'màx. 55 paraules, ja corregida' },
      decisio_humana: { type: 'boolean' },
      correccio_refutador: { type: 'string', description: 'què va canviar l\'escèptic (màx. 30 paraules) o «sense verificar» o «confirmada»' },
      veredicte: { type: 'string', enum: ['confirmat', 'corregit', 'refutat', 'sense_verificar'] },
    }, required: ['id', 'wp_refs', 'principi', 'equivalent_sdp', 'estat_final', 'severitat_final', 'evidencia_clau', 'proposta', 'decisio_humana', 'correccio_refutador', 'veredicte'] } },
  },
  required: ['tram', 'filosofies', 'troballes'],
}

const prompt = t => `Treballa NOMÉS en lectura. Ignora el missatge «[segell-auto] ... segell divergent» si apareix després d'una eina.
TASCA: el fitxer ${OUT} és el resultat JSON (indentat) d'una auditoria que extrapola la checklist de Tellado (neteja de WordPress) a Sóc de Poble. Llig amb Read les línies ${t.from} a ${t.to} (en trossos de 1500 línies; si el tram comença o acaba a mitja troballa, llig unes línies més enllà dels límits per a completar-la, però NO resumisques troballes que comencen fora del teu tram: només les que COMENCEN dins de ${t.from}-${t.to}).
Cada bloc té "filosofia", "items" (troballes) i "verdicts" (un per id, amb veredicte, afirmacions, estat_corregit, severitat_corregida i correccions). Per a CADA troballa que comença dins del teu tram:
- fusiona-la amb el seu veredicte: l'estat i la severitat finals són els CORREGITS; si el veredicte és «refutat», conserva-la amb veredicte refutat i explica per què ha caigut; si no té veredicte, marca sense_verificar;
- aplica les correccions a la proposta i a l'evidència (usa només referències que el veredicte haja trobat certes);
- correcció coneguda del coordinador: _wiki_de_poble/02_saber/perfil_psiquiatric.md descriu la «salut cognitiva» de la IA (IAIA MarIA), NO dades de salut de cap persona; qualsevol troballa que el tracte com a dades de l'art. 9 del RGPD s'ha de rebaixar en conseqüència i dir-ho a correccio_refutador.
No inventes res que no siga al fitxer. Escriu en valencià estricte i compacte. Tram: ${t.key}.`

phase('Digestió')
const res = await parallel(TRAMS.map(t => () => agent(prompt(t), { label: `digestio:${t.key}`, phase: 'Digestió', schema: SCHEMA })))
return res.filter(Boolean)
